static void require(bool v,const char* why){if(!v)throw std::runtime_error(why);}
static void u16(std::vector<U8>& b,U32 p,U16 v){b[p]=U8(v);b[p+1]=U8(v>>8);}
static void u32(std::vector<U8>& b,U32 p,U32 v){for(U32 i=0;i<4;++i)b[p+i]=U8(v>>(8*i));}
static U32 value(U32 face,U32 level,U32 x,U32 y,U32 z){return 0xff000000|((17+face*23+level*5+x*3)&255)|(((29+level*11+y*7)&255)<<8)|(((41+face*13+z*31+level*17)&255)<<16);}
static std::vector<U8> payload(U32 w,U32 h,U32 depth,U32 levels,U32 faces){std::vector<U8> data;for(U32 f=0;f<faces;++f)for(U32 l=0;l<levels;++l)for(U32 z=0;z<std::max(1U,depth>>l);++z)for(U32 y=0;y<std::max(1U,h>>l);++y)for(U32 x=0;x<std::max(1U,w>>l);++x){U32 v=value(f,l,x,y,z);for(U32 c=0;c<4;++c)data.push_back(U8(v>>(c*8)));}return data;}
static std::vector<U8> dds(U32 w,U32 h,U32 depth,U32 levels,bool cube){std::vector<U8> bytes(128);std::memcpy(bytes.data(),"DDS ",4);u32(bytes,4,124);u32(bytes,8,0x2100f|(depth>1?0x800000:0));u32(bytes,12,h);u32(bytes,16,w);u32(bytes,20,w*4);u32(bytes,24,depth);u32(bytes,28,levels);u32(bytes,76,32);u32(bytes,80,0x41);u32(bytes,88,32);u32(bytes,92,0xff0000);u32(bytes,96,0xff00);u32(bytes,100,0xff);u32(bytes,104,0xff000000);u32(bytes,108,0x401008);u32(bytes,112,cube?0xfe00:depth>1?0x200000:0);auto data=payload(w,h,depth,levels,cube?6:1);bytes.insert(bytes.end(),data.begin(),data.end());return bytes;}
static void write(const std::filesystem::path& root,const char* name,const std::vector<U8>& bytes){std::ofstream file(root/name,std::ios::binary);file.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());require(bool(file),"Fixture file write failed");}
static std::vector<U8> bcBundle(U32 w,U32 h,U32 levels,U32 format,bool legacy){std::vector<U8> data;for(U32 l=0;l<levels;++l){const U32 width=std::max(1U,w>>l),height=std::max(1U,h>>l),columns=legacy?width/4:(width+3)/4,rows=legacy?height/4:(height+3)/4;for(U32 y=0;y<rows;++y)for(U32 x=0;x<columns;++x)for(U32 c=0;c<(format==1?8U:16U);++c)data.push_back(U8(11+l*37+y*7+x*3+c));}std::vector<U8> b(20+28+3);u32(b,0,0x425a5232);b[4]=3;b[5]=2;u16(b,6,31);u16(b,8,28);u32(b,12,data.size());u16(b,28,1);u32(b,32,data.size());u16(b,40,format);u16(b,42,levels);u16(b,44,w);u16(b,46,h);b[48]='b';b[49]='c';b.insert(b.end(),data.begin(),data.end());return b;}
static U16 get16(const std::vector<U8>& b,U32 p){require(U64(p)+2<=b.size(),"Fixture metadata U16 exceeds bytes");return U16(b[p])|U16(b[p+1])<<8;}
static U32 get32(const std::vector<U8>& b,U32 p){return get16(b,p)|(U32(get16(b,p+2))<<16);}
static void verifyBundleBytes(Display::ResourceBundler::C_ResourceBundleSingle& loaded,const std::vector<U8>& b){const U32 start=20+get16(b,6);U32 offset=20,index=0;for(;;){const U32 data=get32(b,offset+4),stored=get32(b,offset+12),format=get16(b,offset+20);const auto* texture=loaded.GetTexture2D(index++);require(texture&&texture->GetWidth()==get16(b,offset+24)&&texture->GetHeight()==get16(b,offset+26),"Bundle GPU dimensions differ from stored metadata");U32 consumed=0;for(U32 l=0;l<texture->GetLevels();++l){const U32 w=texture->GetWidth(l),h=texture->GetHeight(l);const bool bc=format==1||format==3||format==5;const U32 pitch=bc?((w+3)/4)*(format==1?8:16):w*(format==6?4:1),rows=bc?(h+3)/4:h;require(U64(consumed)+U64(pitch)*rows<=stored&&U64(start)+data+consumed+U64(pitch)*rows<=b.size(),"Bundle GPU upload read beyond this resource's actual bytes");const auto lock=texture->LockRect2D(l,16);require(lock.pBits,"Bundle GPU bytes could not be read");bool exact=true;for(U32 y=0;y<rows;++y)exact&=!std::memcmp(lock.pBits+y*lock.pitch,b.data()+start+data+consumed+y*pitch,pitch);texture->UnlockRect2D(l);require(exact,"Bundle GPU BC/uncompressed rows differ from exact stored source bytes");consumed+=pitch*rows;}require(consumed==stored,"Bundle omitted nonempty authored mip bytes");const U32 next=get16(b,offset);if(!next)break;offset+=next;}require(index==U32(loaded.GetTexture2DCount()),"Bundle metadata/GPU resource count differs");}
static void verify(const Display::C_Texture& texture,U32 faces,bool volume){for(U32 face=0;face<faces;++face)for(U32 l=0;l<texture.GetLevels();++l){const U32 w=texture.GetWidth(l),h=texture.GetHeight(l),depth=volume?texture.GetDepth(l):1;auto rect=volume?Display::C_ConstLockedRect{}:faces==6?texture.LockRectCube(face,l,16):texture.LockRect2D(l,16);auto box=volume?texture.LockBox3D(l,16):Display2::C_ConstLockedBox{};const U8* bits=volume?box.pBits:rect.pBits;const U32 pitch=volume?box.rowPitch:rect.pitch,slice=volume?box.slicePitch:pitch*h;require(bits,"GPU volume/cube/bundle readback failed");bool valid=true;for(U32 z=0;z<depth;++z)for(U32 y=0;y<h;++y)for(U32 x=0;x<w;++x){U32 actual;std::memcpy(&actual,bits+U64(z)*slice+U64(y)*pitch+x*4,4);valid&=actual==value(face,l,x,y,z);}if(volume)texture.UnlockBox3D(l);else if(faces==6)texture.UnlockRectCube(face,l);else texture.UnlockRect2D(l);require(valid,"GPU rows/slices/faces/mips disagree with authored file bytes");}}
static std::vector<U8> bundle(U32 version,bool compressed){auto data=payload(5,3,1,3,1);const std::string name="SoUrCe.DDS";const U32 record=version==3?28:20;std::vector<U8> info(record+name.size()+1);u16(info,2,0);u32(info,4,0);u16(info,8,1);const U32 fields=version==3?20:version==2?12:10;u16(info,fields,6);u16(info,fields+2,3);u16(info,fields+4,5);u16(info,fields+6,3);if(version==3)u32(info,12,data.size());std::memcpy(info.data()+record,name.c_str(),name.size()+1);
    std::vector<U8> stored=data;if(compressed){uLongf size=compressBound(data.size());stored.resize(size);require(compress2(stored.data(),&size,data.data(),data.size(),Z_BEST_COMPRESSION)==Z_OK,"Authored zlib compression failed");stored.resize(size);}
    const U32 header=version==1?16:20;std::vector<U8> bytes(header);u32(bytes,0,version==1?0x425a5231:0x425a5232);bytes[4]=version;bytes[5]=2;u16(bytes,6,info.size());u16(bytes,8,record);
    if(version==1)u32(bytes,12,compressed?(0x80000000U|U32(stored.size()+8)):U32(data.size()));else {u16(bytes,10,compressed?1:0);u32(bytes,12,data.size());u32(bytes,16,compressed?stored.size():0);}bytes.insert(bytes.end(),info.begin(),info.end());if(version==1&&compressed){const U32 p=bytes.size();bytes.resize(p+8);u32(bytes,p,data.size());u32(bytes,p+4,stored.size());}bytes.insert(bytes.end(),stored.begin(),stored.end());return bytes;
}
int main(int argc,char** argv){try{require(argc==2,"Expected writable fixture directory");const auto root=std::filesystem::absolute(argv[1]);std::filesystem::create_directories(root);auto& fs=Sys::C_FileSystem::Instance();Sys::SetDefaultFileSystem(&fs);require(fs.SetWorkingDirectory(root.c_str()),"Filesystem fixture setup failed");Display::C_Device device;Display::C_DeviceParams config;config.m_Width=config.m_Height=16;require(device.Create(config),"Native Display device failed");
    const auto plane=dds(5,3,1,3,false);write(root,"plane.dds",plane);Display2::C_TextureParams metadata;require(Display2::LoadDDSTextureFromFile("plane.dds",&metadata)&&!metadata.m_pFileData&&metadata.m_MipOffset==128,"DDS metadata entry point did not select actual file streaming");Display::C_Texture2D texture2D;require(Display2::CreateTexture2DFromFile("plane.dds",&texture2D),"Lower streamed DDS file helper failed");verify(texture2D,1,false);device.DestroyTexture2D(&texture2D);
    auto volume=dds(5,3,3,3,false),cube=dds(4,4,1,3,true);write(root,"volume.dds",volume);write(root,"cube.dds",cube);Display::C_Texture3D texture3D;Display::C_TextureCube textureCube;require(Display::CreateTexture3DFromFile("volume.dds",&texture3D),"Original DDS volume helper failed");verify(texture3D,1,true);require(Display::CreateTextureCubeFromFile("cube.dds",&textureCube),"Original DDS cube helper failed");verify(textureCube,6,false);require(!Display::CreateTexture3DFromFile("cube.dds",&texture3D),"Created texture was overwritten");verify(texture3D,1,true);device.DestroyTexture3D(&texture3D);device.DestroyTextureCube(&textureCube);
    {auto bc=dds(8,8,1,4,true);bc.resize(128);u32(bc,80,4);u32(bc,84,0x31545844);for(U32 f=0;f<6;++f)for(U32 l=0;l<4;++l){const U32 side=std::max(1U,8U>>l),blocks=((side+3)/4)*((side+3)/4);for(U32 i=0;i<blocks;++i){U8 block[8]={U8(0x11+f),U8(0x22+l),U8(0x33+i),0,0,0,0,0};bc.insert(bc.end(),block,block+8);}}write(root,"bc-cube.dds",bc);require(Display::CreateTextureCubeFromFile("bc-cube.dds",&textureCube),"BC cube DDS allocation/upload failed");for(U32 f=0;f<6;++f)for(U32 l=0;l<4;++l){auto map=textureCube.LockRectCube(f,l,16);require(map.pBits,"BC cube GPU readback failed");const U32 rowBlocks=(textureCube.GetWidth(l)+3)/4,rows=(textureCube.GetHeight(l)+3)/4;bool valid=true;for(U32 y=0;y<rows;++y)for(U32 x=0;x<rowBlocks;++x){const U8 block[8]={U8(0x11+f),U8(0x22+l),U8(0x33+y*rowBlocks+x),0,0,0,0,0};valid&=!std::memcmp(map.pBits+y*map.pitch+x*8,block,8);}textureCube.UnlockRectCube(f,l);require(valid,"BC cube face/block/tail bytes changed during GPU upload");}device.DestroyTextureCube(&textureCube);}
    auto truncated=volume;truncated.pop_back();write(root,"short.dds",truncated);auto partial=cube;u32(partial,112,0x7e00);write(root,"partial.dds",partial);auto levels=volume;u32(levels,28,32);write(root,"levels.dds",levels);for(const char* file:{"cube.dds","short.dds","levels.dds","missing.dds"})require(!Display::CreateTexture3DFromFile(file,&texture3D)&&!texture3D.IsCreated(),"Invalid/truncated/mismatched volume DDS created a GPU texture");for(const char* file:{"volume.dds","partial.dds","short.dds"})require(!Display::CreateTextureCubeFromFile(file,&textureCube)&&!textureCube.IsCreated(),"Invalid/truncated/mismatched cube DDS created a GPU texture");
    Display::ResourceBundler::C_ResourceBundleSingle loaded;for(U32 version:{1U,2U,3U})for(bool compressed:{false,true}){const auto bytes=bundle(version,compressed);write(root,"sample.bzr",bytes);require(loaded.Create(Sys::C_FilePath("sample.bzr"))&&loaded.GetTexture2DCount()==1&&loaded.ResourceCount()==1,"Original BZR reader/real GPU bundle creation failed");auto* texture=loaded.GetTexture2D(Util::C_String("SOURCE.DDS"));require(texture&&texture==loaded.GetTexture2D(0)&&std::strcmp(loaded.GetResourceName(0),"source.dds")==0&&loaded.CalculateVideoMemorySize()==72,"Bundle resource name/count/metadata differs from original API");verify(*texture,1,false);loaded.Destroy();loaded.Destroy();require(!loaded.GetTexture2DCount(),"Bundle teardown retained resources");}
    {auto original=bundle(3,false);const char names[]="source.dds\0second.dds\0";const U32 infoSize=56+sizeof(names);std::vector<U8> multi(20+infoSize+144);std::memcpy(multi.data(),original.data(),20);u16(multi,6,infoSize);u16(multi,8,56);u32(multi,12,144);std::memcpy(multi.data()+20,original.data()+20,28);std::memcpy(multi.data()+48,original.data()+20,28);u16(multi,20,28);u16(multi,50,11);u32(multi,52,72);std::memcpy(multi.data()+76,names,sizeof(names));std::memcpy(multi.data()+20+infoSize,original.data()+original.size()-72,72);std::memcpy(multi.data()+20+infoSize+72,original.data()+original.size()-72,72);write(root,"multi.bzr",multi);require(loaded.Create(Sys::C_FilePath("multi.bzr"))&&loaded.GetTexture2DCount()==2&&loaded.CalculateVideoMemorySize()==144,"Original bundle offset chain/count/reserve failed");verify(*loaded.GetTexture2D(0),1,false);verify(*loaded.GetTexture2D(Util::C_String("SECOND.DDS")),1,false);loaded.Destroy();}
    for(bool legacy:{false,true})for(U32 format:{1U,3U,5U})for(bool rectangle:{false,true}){const U32 w=rectangle?64:16,h=rectangle?8:16,levels=rectangle?7:5;auto b=bcBundle(w,h,levels,format,legacy);write(root,"bc.bpr",b);require(loaded.Create(Sys::C_FilePath("bc.bpr")),"Original BC bundle layout failed");require(loaded.GetTexture2D(0)->GetLevels()==(legacy?(rectangle?2U:3U):levels),"Missing original BC tail mips remained exposed to GPU sampling");verifyBundleBytes(loaded,b);loaded.Destroy();if(legacy){u32(b,32,get32(b,32)-1);write(root,"bc-bad.bpr",b);require(!loaded.Create(Sys::C_FilePath("bc-bad.bpr"))&&!loaded.GetTexture2DCount(),"Incomplete authored BC block prefix was accepted");}}
    if(const char* retail=std::getenv("BLUR_MAC_BPR_RETAIL_DIR")){for(const char* name:{"ui_common.bpr","ui_font_eur.bpr"}){const auto path=std::filesystem::path(retail)/name;std::ifstream input(path,std::ios::binary);require(bool(input),"Private original BPR fixture is absent");const std::vector<U8> b{std::istreambuf_iterator<char>(input),std::istreambuf_iterator<char>()};require(loaded.Create(Sys::C_FilePath(path.string().c_str())),"Original installed BPR failed native GPU creation");verifyBundleBytes(loaded,b);std::cout<<"Original "<<name<<": "<<loaded.GetTexture2DCount()<<" textures, exact GPU rows/mips validated\n";loaded.Destroy();}}
    auto good=bundle(3,false);auto shortFile=good;shortFile.pop_back();auto chain=good;u16(chain,20,2);auto badName=good;u16(badName,22,0xffff);auto badPayload=good;u32(badPayload,24,0xffff);auto unknown=good;unknown[4]=99;auto corrupt=bundle(3,true);corrupt.back()^=0x55;for(const auto& bytes:{shortFile,chain,badName,badPayload,unknown,corrupt}){write(root,"bad.bzr",bytes);require(!loaded.Create(Sys::C_FilePath("bad.bzr"))&&!loaded.GetTexture2DCount(),"Invalid bundle reported success or retained partial GPU resources");}
    require(device.GetDisplay2().WaitIdle(),"File texture GPU completion failed");device.Destroy();Sys::SetDefaultFileSystem(nullptr);std::cout<<"Native file Display: original DDS 3D/cube rows/slices/faces/mips, BZR1/BZR2 v2/v3 raw+zlib GPU textures, naming/lifetime/bounds/error rollback passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
